package flushblockcache

import (
	"context"
	"strconv"
	"testing"

	"github.com/apache/kvrocks/tests/gocase/util"
	"github.com/redis/go-redis/v9"
	"github.com/stretchr/testify/require"
)

func getBlockCacheSize(rdb *redis.Client) (int64, error) {
	value := util.FindInfoEntry(rdb, "block_cache_usage", "rocksdb")
	return strconv.ParseInt(value, 10, 64)
}

func TestFlushBlockCache(t *testing.T) {
	configs := map[string]string{}
	srv := util.StartServer(t, configs)
	defer srv.Close()

	rdb := srv.NewClient()
	defer func() {
		require.NoError(t, rdb.Close())
	}()

	ctx := context.Background()

	t.Run("flushblockcache", func(t *testing.T) {
		_, err := rdb.Do(ctx, "SET", "A", "KVROCKS").Result()
		require.NoError(t, err)
		_, err = rdb.Do(ctx, "FLUSHMEMTABLE").Result()
		require.NoError(t, err)
		_, err = rdb.Do(ctx, "GET", "A").Result()
		require.NoError(t, err)
		initCacheSize, err := getBlockCacheSize(rdb)
		require.NoError(t, err)
		_, err = rdb.Do(ctx, "FLUSHBLOCKCACHE").Result()
		require.NoError(t, err)
		cacheSize, err := getBlockCacheSize(rdb)
		require.NoError(t, err)
		require.Less(t, cacheSize, initCacheSize)
		require.Equal(t, "KVROCKS", rdb.Do(ctx, "GET", "A").Val())
	})
}

func TestFlushBlockCacheInvalid(t *testing.T) {
	srv := util.StartServer(t, map[string]string{})
	defer srv.Close()

	rdb := srv.NewClient()
	defer func() {
		require.NoError(t, rdb.Close())
	}()

	ctx := context.Background()

	t.Run("invalid arguments", func(t *testing.T) {
		_, err := rdb.Do(ctx, "FLUSHBLOCKCACHE", "ARG").Result()
		require.Contains(t, err.Error(), "wrong number of arguments")
	})
}

func TestFlushBlockCacheAdminPermission(t *testing.T) {
	srv := util.StartServer(t, map[string]string{
		"requirepass": "admin",
	})
	defer srv.Close()

	ctx := context.Background()

	adminClient := srv.NewClientWithOption(&redis.Options{Password: "admin"})
	defer func() { require.NoError(t, adminClient.Close()) }()

	require.NoError(t, adminClient.Do(ctx, "NAMESPACE", "ADD", "test_ns", "test_token").Err())

	userClient := srv.NewClientWithOption(&redis.Options{Password: "test_token"})
	defer func() { require.NoError(t, userClient.Close()) }()

	t.Run("Non-admin user should be rejected", func(t *testing.T) {
		require.ErrorContains(t, userClient.Do(ctx, "FLUSHBLOCKCACHE").Err(), "admin")
	})

	t.Run("Admin user should be allowed", func(t *testing.T) {
		require.NoError(t, adminClient.Do(ctx, "FLUSHBLOCKCACHE").Err())
	})
}

